'use client';

import * as React from 'react';
import { cn } from '@/lib/utils';
import { Button } from '../button/Button';
import { FilterChips, type FilterChip } from '../filter-chips/FilterChips';

export type AppliedFiltersProps = React.HTMLAttributes<HTMLDivElement> & {
  /** Active filters to display. */
  filters: FilterChip[];
  /** Clear-all action. */
  onClearAll?: () => void;
  /** Opens the filter panel for editing. */
  onEdit?: () => void;
  /** Optional summary text; defaults to "N active". */
  label?: string;
  /** Shown when there are no filters. */
  emptyLabel?: string;
  /** Edit action label. Default "Edit filters". */
  editLabel?: string;
};

/**
 * Applied-filter summary for a dashboard or directory. Adds a live count and
 * an optional edit action around FilterChips, so the applied set stays visible
 * even when the filter panel is closed.
 */
export const AppliedFilters = React.forwardRef<HTMLDivElement, AppliedFiltersProps>(
  function AppliedFilters(
    {
      filters,
      onClearAll,
      onEdit,
      label,
      emptyLabel,
      editLabel = 'Edit filters',
      className,
      ...props
    },
    ref
  ) {
    const summary = label ?? `${filters.length} active`;

    if (filters.length === 0) {
      return emptyLabel ? (
        <div ref={ref} className={cn('text-sm text-muted-foreground', className)} {...props}>
          {emptyLabel}
        </div>
      ) : null;
    }

    return (
      <div
        ref={ref}
        aria-live="polite"
        className={cn('flex flex-wrap items-center gap-2', className)}
        {...props}
      >
        <span className="text-xs font-medium uppercase tracking-wide text-muted-foreground">{summary}</span>
        <FilterChips filters={filters} onClearAll={onClearAll} />
        {onEdit && (
          <Button type="button" variant="ghost" size="sm" onClick={onEdit}>
            {editLabel}
          </Button>
        )}
      </div>
    );
  }
);

{
  "id": "applied-filters",
  "name": "AppliedFilters",
  "tier": "molecule",
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.7.0",
  "sourceDir": "applied-filters",
  "exportName": "AppliedFilters",
  "description": "Applied-filter summary with a live count, removable chips and an edit action.",
  "designIntent": "Filter panels close, collapse or move into a drawer. AppliedFilters keeps the active set visible outside the panel and gives the user one place to edit or clear it.",
  "props": [
    {
      "name": "filters",
      "type": "FilterChip[]",
      "required": true,
      "description": "Active filters to display."
    },
    {
      "name": "onClearAll",
      "type": "() => void",
      "required": false,
      "description": "Clear-all action."
    },
    {
      "name": "onEdit",
      "type": "() => void",
      "required": false,
      "description": "Opens the filter panel for editing."
    },
    {
      "name": "label",
      "type": "string",
      "required": false,
      "description": "Optional summary text; defaults to N active."
    },
    {
      "name": "emptyLabel",
      "type": "string",
      "required": false,
      "description": "Shown when there are no filters."
    },
    {
      "name": "editLabel",
      "type": "string",
      "required": false,
      "defaultValue": "Edit filters",
      "description": "Edit action label."
    }
  ],
  "examples": [
    {
      "title": "Applied dashboard filters",
      "code": "<AppliedFilters\n  filters={[\n    { key: 'industry', label: 'Industry', value: 'Technology', onRemove: remove },\n  ]}\n  onClearAll={clearAll}\n  onEdit={openPanel}\n/>",
      "description": "A count, removable chip and edit action."
    }
  ],
  "antiPatterns": [
    {
      "title": "Don't duplicate FilterChips",
      "explanation": "AppliedFilters already renders FilterChips. Use one summary per filter surface.",
      "example": "// Avoid two chip rows with the same filters"
    }
  ],
  "accessibility": [
    {
      "feature": "Live summary",
      "implementation": "The wrapper uses aria-live=polite so count changes are announced",
      "userRequirements": "Keep the summary short"
    },
    {
      "feature": "Remove and clear",
      "implementation": "Delegates to FilterChips, which names each remove button and the clear action",
      "userRequirements": "Provide stable filter keys"
    }
  ],
  "compositionRules": [
    {
      "component": "FilterPanel",
      "relationship": "Pair AppliedFilters with the panel; onEdit opens the panel or drawer",
      "example": "<AppliedFilters filters={chips} onEdit={() => setOpen(true)} />"
    }
  ],
  "relatedComponents": [
    "FilterChips",
    "FilterPanel",
    "FilterBar"
  ]
}
